export const getProductsSetTeamProductsUrl = (teamId: string,) => {




  return `/api/product-management/products/by-team/${encodeURIComponent(String(teamId))}`
}

/**
 * **Replaces the team's links as a whole**: the team is linked to every product in `productIds` and **unlinked from every product not in it** — read the current set with `Products_GetTeamProducts` first, and send it back with your change. An empty list unlinks the team from everything.
 *
 * All or nothing across every product it touches, and each product records its own linking or unlinking in its Activity. The team must be active to be linked to a new product; an inactive team can still be unlinked. At most 500 products. Link the **most specific products** the team works on, since each product's teams roll up to its ancestors.
 * @summary Set the products a team or team of teams is linked to.
 */
export const productsSetTeamProducts = async (teamId: string,
    setTeamProductsRequest: SetTeamProductsRequest, options?: Parameters<typeof apiFetch>[1]): Promise<void> => {

  return apiFetch<void>(getProductsSetTeamProductsUrl(teamId),
  {
    ...options,
    method: 'PUT',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(setTeamProductsRequest)
  }
);}


