export const getProductsSetTeamsUrl = (id: string,) => {




  return `/api/product-management/products/${encodeURIComponent(String(id))}/teams`
}

/**
 * **Replaces the product's own team links as a whole**: every team in `teamIds` is linked and **every team not in it is unlinked** — read the current set first (`Products_GetProduct` carries the product's own `teams`) and send it back with your change. An empty list unlinks them all. Teams linked to the products beneath it are not affected.
 *
 * All or nothing: when a team cannot be linked — it is inactive, or does not exist — nothing changes, and the refusal names it. An inactive team already linked can stay. At most 100 teams. To add or remove one team, `Products_LinkTeam` and `Products_UnlinkTeam` touch only that team; to set the products of one team, use `Products_SetTeamProducts`.
 * @summary Set the teams and teams of teams linked to a product.
 */
export const productsSetTeams = async (id: string,
    setProductTeamsRequest: SetProductTeamsRequest, options?: Parameters<typeof apiFetch>[1]): Promise<void> => {

  return apiFetch<void>(getProductsSetTeamsUrl(id),
  {
    ...options,
    method: 'PUT',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(setProductTeamsRequest)
  }
);}


